function validate([rectangles]) {
  if (!Array.isArray(rectangles) || rectangles.length < 1 || rectangles.length > 20000) return 'rectangles needs 1 to 20000 entries.';
  for (const r of rectangles) {
    if (!Array.isArray(r) || r.length !== 4 || !r.every(Number.isInteger)) return 'Each rectangle is [x, y, a, b] of integers.';
    if (r.some(v => v < -100000 || v > 100000)) return 'Coordinates are between -10^5 and 10^5.';
    if (r[0] >= r[2] || r[1] >= r[3]) return 'Each rectangle needs x < a and y < b.';
  }
  return null;
}

