function isRectangleCover(rectangles) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let area = 0;
  const corners = new Set();

  for (const [x, y, a, b] of rectangles) {
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, a);
    maxY = Math.max(maxY, b);
    area += (a - x) * (b - y);
    for (const corner of [`${x},${y}`, `${x},${b}`, `${a},${y}`, `${a},${b}`]) {
      if (corners.has(corner)) {
        corners.delete(corner);
      } else {
        corners.add(corner);
      }
    }
  }

  if (area !== (maxX - minX) * (maxY - minY)) {
    return false;
  }
  if (corners.size !== 4) {
    return false;
  }
  return corners.has(`${minX},${minY}`) && corners.has(`${minX},${maxY}`)
    && corners.has(`${maxX},${minY}`) && corners.has(`${maxX},${maxY}`);
}

