function isRectangleCover(rectangles) {
  // Cut the plane along every rectangle edge and count how often each small cell is covered.
  const xs = [...new Set(rectangles.flatMap(r => [r[0], r[2]]))].sort((p, q) => p - q);
  const ys = [...new Set(rectangles.flatMap(r => [r[1], r[3]]))].sort((p, q) => p - q);
  const count = xs.map(() => ys.map(() => 0));
  for (const [x, y, a, b] of rectangles) {
    for (let i = xs.indexOf(x); xs[i] < a; i++) {
      for (let j = ys.indexOf(y); ys[j] < b; j++) count[i][j]++;
    }
  }
  for (let i = 0; i + 1 < xs.length; i++) {
    for (let j = 0; j + 1 < ys.length; j++) if (count[i][j] !== 1) return false;
  }
  return true;
}

