function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const width = large ? int(30, 40) : int(1, 5);
  const height = large ? int(30, 50) : int(1, 5);
  const lines = count => {
    const out = [large ? int(-100000, -50000) : int(-3, 2)];
    for (let i = 0; i < count; i++) out.push(out[i] + (large ? int(1, 3000) : int(1, 2)));
    return out;
  };
  const xs = lines(width), ys = lines(height);
  // Tile a width x height grid of cells with random rectangles (pinwheels included).
  const used = Array.from({ length: height }, () => new Array(width).fill(false));
  let rects = [];
  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      if (used[r][c]) continue;
      let maxW = 0;
      while (c + maxW < width && !used[r][c + maxW]) maxW++;
      const w = int(1, Math.min(maxW, 3));
      let maxH = 0;
      while (r + maxH < height && used[r + maxH].slice(c, c + w).every(u => !u)) maxH++;
      const h = int(1, Math.min(maxH, 3));
      for (let i = r; i < r + h; i++) for (let j = c; j < c + w; j++) used[i][j] = true;
      rects.push([xs[c], ys[r], xs[c + w], ys[r + h]]);
    }
  }
  for (let i = rects.length - 1; i > 0; i--) {
    const j = int(0, i);
    [rects[i], rects[j]] = [rects[j], rects[i]];
  }
  // Half of the inputs stay perfect; the rest get one small defect.
  if (rand() < 0.5) {
    const mode = int(0, 3);
    const pick = int(0, rects.length - 1);
    if (mode === 0 && rects.length > 1) rects.splice(pick, 1);
    else if (mode === 1 && rects.length < 2000) rects.push(rects[pick].slice());
    else if (mode === 2) {
      for (;;) {
        const moved = rects[pick].slice();
        moved[int(0, 3)] += rand() < 0.5 ? -1 : 1;
        if (moved[0] < moved[2] && moved[1] < moved[3] && moved.every(v => v >= -100000 && v <= 100000)) { rects[pick] = moved; break; }
      }
    } else if (rects.length < 2000) {
      const x = int(xs[0], xs[width] - 1), y = int(ys[0], ys[height] - 1);
      rects.splice(pick, 0, [x, y, int(x + 1, xs[width]), int(y + 1, ys[height])]);
    }
  }
  return [rects];
}
